if(event){html+=`<div class="sectionlabel">选中跳变点</div>${field('时间 ns','eventTime',event.t,'number','step="any" '+(event.t===0?'disabled':''))}${field('段值','eventValue',event.v,'text','maxlength="256"')}<div class="propertybuttons"><button id="deleteEvent" ${event.t===0?'disabled':''}>删除跳变点</button><button id="editSegment">编辑完整段</button></div>`}else html+=`<div class="sectionlabel">跳变点</div><div class="readout">${s.events.length} events<br>选择跳变点以精确编辑</div>`;
