function addSignal(type){if(doc.signals.length>=512)return toast('最多支持 512 路信号');checkpoint();let s=WC.signal((type==='clock'?'clk':type==='bus'?'data':type==='separator'?'分隔':'signal')+'_'+doc.signals.length,type,[{t:0,v:type==='bus'?'0x00':'0'}],'',doc.signals.length);if(type==='clock')WC.clock(s,doc.duration);doc.signals.push(s);selection=new Set([s.id]);chosen=null;commit();let y=rowY(s.id);$('canvasScroll').scrollTop=Math.max(0,y-100)}
