function zoom(factor,fit=false){const vp=$('canvasScroll'),center=(vp.scrollLeft+vp.clientWidth/2-LEFT)/px;px=fit?Math.max(.000001,(vp.clientWidth-LEFT-45)/doc.duration):Math.min(10000,Math.max(.000001,px*factor));renderCanvas();vp.scrollLeft=Math.max(0,LEFT+center*px-vp.clientWidth/2);if(fit)vp.scrollLeft=0;$('zoomLabel').textContent=Math.round(px/5*100)+'%'}$('zoomIn').onclick=()=>zoom(1.35);$('zoomOut').onclick=()=>zoom(1/1.35);$('fit').onclick=()=>zoom(1,true);
