$('rowUp').onclick=()=>shiftRows(-1);$('rowDown').onclick=()=>shiftRows(1);$('deleteRows').onclick=()=>{if(selection.size)deleteSignals(selection)};$('duplicate').onclick=()=>{if(!selection.size)return;if(doc.signals.length+selection.size>512)return toast('最多支持 512 路信号');checkpoint();let dup=doc.signals.filter(s=>selection.has(s.id)).map(s=>({...WC.copy(s),id:WC.uid(),name:s.name+'_copy'}));doc.signals.push(...dup);selection=new Set(dup.map(s=>s.id));chosen=null;commit()};
