function rangeDialog(){if(!selection.size)return toast('先选中要编辑的信号');let a=Math.min(range?.a??0,range?.b??doc.duration),b=Math.max(range?.a??0,range?.b??doc.duration);modal('时间区间 · '+selection.size+' 路信号',`<div class="fields">${field('开始 ns','rangeA',a,'number','step="any"')}${field('结束 ns','rangeB',b,'number','step="any"')}<label class="field">操作<select id="rangeOp"><option value="fill">填入序列</option><option value="invert">翻转数字电平</option><option value="copy">复制</option><option value="paste">粘贴（从开始位置）</option><option value="delay">延迟选中信号</option><option value="insert">全工程插入空白时间</option><option value="delete">全工程删除时间段</option></select></label></div>${field('序列每项时长 ns / 延迟量 ns','rangeStep',doc.grid,'number','step="any"')}<p>序列以逗号分隔，支持重复：<code>0*4,1*8,X*2</code>。选择多路信号时应用相同序列。插入 / 删除时间会作用于全部信号和标注。</p><textarea id="rangeSeq">0*4,1*4</textarea>`,()=>{let start=number($('rangeA').value,'开始'),end=number($('rangeB').value,'结束'),op=$('rangeOp').value,step=number($('rangeStep').value,'步长',1e-6);if(start>=end||end>doc.duration)throw Error('区间超出工程时间');let d=WC.copy(doc),targets=d.signals.filter(s=>selection.has(s.id));if(op==='copy'){clipboard=WC.copyRange(doc,[...selection],start,end);range={a:start,b:end};render();toast('已复制 '+selection.size+' 路 / '+WC.fmt(end-start)+' ns');return}if(op==='paste'){if(!clipboard)throw Error('剪贴板为空');WC.pasteRange(d,[...selection],clipboard,start)}if(op==='fill'){const seq=WC.parseSequence($('rangeSeq').value);if(!seq.length)throw Error('请填写序列');if(Math.ceil((end-start)/step)>100000)throw Error('填充超过 100000 段');for(const s of targets){let restore=WC.valueAt(s,end),events=[];for(let t=start,i=0;t<end;t=start+(++i)*step)events.push({t,v:seq[i%seq.length]});s.events=s.events.filter(e=>e.t<start||e.t>=end).concat(events,end<d.duration?[{t:end,v:restore}]:[]);s.events=WC.normalize(s.events,d.duration,s.type)}}if(op==='invert')for(const s of targets){if(!['digital','clock'].includes(s.type))continue;const before=WC.valueAt(s,start),after=WC.valueAt(s,end);s.events.push({t:start,v:before});if(end<d.duration)s.events.push({t:end,v:after});s.events=WC.normalize(s.events,d.duration,s.type);s.events=s.events.map(e=>e.t>=start&&e.t<end?{t:e.t,v:e.v==='1'?'0':e.v==='0'?'1':e.v}:e)}if(op==='delay')for(const s of targets){s.events=[{t:0,v:s.type==='bus'?'IDLE':'0'},...s.events.map(e=>({t:e.t+step,v:e.v})).filter(e=>e.t<d.duration)]}
if(op==='insert'){const length=end-start;d.duration+=length;for(const s of d.signals){const v=WC.valueAt(s,start);s.events=s.events.map(e=>e.t>=start?{t:e.t+length,v:e.v}:e);s.events.push({t:start,v})}for(const a of d.annotations){if(a.t>=start)a.t+=length;if(a.t2>=start)a.t2+=length}}if(op==='delete'){let len=end-start;if(len>=d.duration)throw Error('不能删除全部时间');for(const s of d.signals){let after=WC.valueAt(s,end);s.events=s.events.filter(e=>e.t<start||e.t>=end).map(e=>({t:e.t>=end?e.t-len:e.t,v:e.v}));s.events.push({t:start,v:after});s.events=WC.normalize(s.events,d.duration-len,s.type)}const map=t=>t<start?t:t<end?start:t-len;for(const a of d.annotations){a.t=map(a.t);a.t2=map(a.t2)}d.duration-=len}WC.validate(d);checkpoint();doc=d;chosen=null;range=null;commit()})}$('rangeEdit').onclick=rangeDialog;
function generatorDialog(){const s=selectedSignal();if(!s||s.type==='separator')return toast('先选择输出信号');modal('算法 / 数值生成器 · '+esc(s.name),`<div class="fields"><label class="field">预设<select id="preset"><option value="i % 16">模16计数器</option><option value="i ^ (i >> 1)">Gray 码</option><option value="(i % 8) < 3">PWM</option><option value="prev + s0">累加器</option><option value="sin(i * 0.2)">正弦曲线</option></select></label>${field('采样间隔 ns','genStep',doc.grid,'number','step="any"')}${field('初始 prev','genPrev',0,'number','step="any"')}</div><textarea id="genExpression" spellcheck="false">i % 16</textarea><p>变量：i 样本编号、t 时间(ns)、prev 上次输出；s0 / s1 引用对应信号在 t 的数值。支持 + − * / %、比较、位运算与 sin / cos / abs / floor。位运算使用 32 位整数；不执行脚本或 RTL。</p>`,()=>{let step=number($('genStep').value,'采样间隔',1e-6),prev=number($('genPrev').value,'初始值',-1e15),count=Math.ceil(doc.duration/step),expr=$('genExpression').value.trim(),refs=[...new Set(expr.match(/\bs\d+\b/g)||[])];if(count>30000)throw Error('单次生成最多 30000 个采样点');let events=[];for(let i=0;i<count;i++){let t=i*step,vars={i,t,prev};for(const key of refs){let sig=doc.signals[+key.slice(1)],v=sig?WC.valueAt(sig,t):undefined;if(v===undefined||v.trim()===''||!Number.isFinite(Number(v)))throw Error(key+' 在 '+WC.fmt(t)+' ns 不是数字');vars[key]=Number(v)}prev=evaluateExpression(expr,vars);events.push({t,v:['clock','digital'].includes(s.type)?(prev?'1':'0'):String(+prev.toPrecision(12))})}const d=WC.copy(doc);d.signals.find(n=>n.id===s.id).events=WC.normalize(events,d.duration,s.type);WC.validate(d);checkpoint();doc=d;chosen=null;commit()});$('preset').onchange=()=>$('genExpression').value=$('preset').value}$('generator').onclick=generatorDialog;
function loadProject(d){if(db)db.transaction('projects','readwrite').objectStore('projects').put({id:doc.id,title:doc.title,updated:Date.now(),data:WC.copy(doc)});checkpoint();doc=WC.validate(d);selection=new Set(doc.signals.length?[doc.signals[0].id]:[]);chosen=null;range=null;collapsed.clear();filter='';$('search').value='';saveHandle=null;commit();zoom(1,true);$('canvasScroll').scrollTop=0}
$('template').onchange=()=>{let k=$('template').value;if(!k)return;modal('载入模板',`<p>当前工程会先保留在本机工程库。载入后也可使用撤销恢复。</p>`,()=>{loadProject(WC.template(k))},'载入');$('template').value=''};
$('newProject').onclick=()=>modal('新建工程',field('工程名称','newName','未命名时序')+'<p>当前工程会保留在本机工程库，也可以撤销恢复。</p>',()=>{let d=WC.empty();d.title=$('newName').value.trim().slice(0,200)||d.title;loadProject(d)});
function download(name,data,type){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
$('saveProject').onclick=()=>{download(doc.title+'.wavecraft.json',JSON.stringify(doc,null,2),'application/json');toast('已下载工程文件；包含全部波形、分组和标注')};$('openProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async()=>{let f=$('projectFile').files[0];if(!f)return;try{if(f.size>50e6)throw Error('文件超过 50 MB');let text=await f.text(),d=f.name.toLowerCase().endsWith('.vcd')?WC.parseVCD(text):WC.validate(JSON.parse(text));loadProject(d);toast('工程已打开；旧版本工程会自动迁移')}catch(e){toast('打开失败：'+e.message)}$('projectFile').value=''};
$('recent').onclick=()=>{if(!db)return toast('工程库暂不可用，请使用下载的工程文件');const req=db.transaction('projects','readonly').objectStore('projects').getAll();req.onsuccess=()=>{const list=req.result.sort((a,b)=>b.updated-a.updated);modal('本机工程库',`<p>仅存储在当前浏览器中。清理浏览器数据会删除本机工程，请下载文件备份。</p><div>${list.slice(0,40).map((p,i)=>`<div class="recentitem"><div><strong>${esc(p.title)}</strong><small>${new Date(p.updated).toLocaleString()} · ${p.data.signals.length} 路信号</small></div><button data-project="${i}">打开</button></div>`).join('')}</div>`,null);document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{const p=list[+b.dataset.project];loadProject(p.data);$('dialog').close()})}};
function fullSVG(scale=px){let v=waveformSVG(true,scale);return{...v,source:`<svg xmlns="http://www.w3.org/2000/svg" width="${v.w}" height="${v.h}" viewBox="0 0 ${v.w} ${v.h}">${v.content}</svg>`}}
async function pngExport(){let v=fullSVG(Math.min(px,Math.max(.000001,(12000-LEFT)/doc.duration)));if(v.w*v.h>30000000||v.h>16000)throw Error('PNG 图片过大，请使用 SVG；SVG 不受画布像素限制');const url=URL.createObjectURL(new Blob([v.source],{type:'image/svg+xml'}));try{let img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('浏览器无法生成 PNG'));img.src=url});let c=document.createElement('canvas');c.width=v.w;c.height=v.h;c.getContext('2d').drawImage(img,0,0);let b=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!b)throw Error('PNG 导出失败');download(doc.title+'.png',b,'image/png')}finally{URL.revokeObjectURL(url)}}
$('exportMenu').onclick=()=>{modal('导出设计文档',`<div class="exportchoices"><button id="exportSvg">SVG 矢量图<small>全部信号与标注 · 白底 · 可缩放</small></button><button id="exportPng">PNG 图片<small>自动限制画布大小 · 适合报告</small></button><button id="exportVcd">VCD 仿真交换<small>数字与总线 · 不含文字标注</small></button><button id="exportPrint">打印 / 保存 PDF<small>打开打印视图后由浏览器保存</small></button></div><p>导出包含折叠和搜索隐藏的全部信号。底层数据按实际值输出，差分 / 反相为绘图显示设置。</p>`,null);$('exportSvg').onclick=()=>{download(doc.title+'.svg',fullSVG().source,'image/svg+xml');toast('SVG 已导出')};$('exportPng').onclick=async()=>{try{await pngExport();toast('PNG 已导出')}catch(e){toast(e.message)}};$('exportVcd').onclick=()=>{try{download(doc.title+'.vcd',WC.exportVCD(doc),'text/plain');toast('VCD 已导出')}catch(e){toast(e.message)}};$('exportPrint').onclick=()=>{const v=fullSVG(Math.min(px,1200/doc.duration)),win=window.open('','_blank');if(!win)return toast('请允许弹出窗口，或导出 SVG 后打印');win.document.write(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(doc.title)}</title><style>body{font:12px sans-serif;margin:24px}svg{width:100%;height:auto}button{padding:10px;margin:16px 0}@media print{button{display:none}@page{size:A3 landscape;margin:12mm}}</style><h2>${esc(doc.title)}</h2><p>${esc(doc.description)}</p><button onclick="window.print()">打印 / 保存 PDF</button>${v.source}</html>`);win.document.close()}};
$('theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('wavecraft-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}renderCanvas()};
function help(){modal('Wavecraft Studio · 操作指南',`<p><kbd>V</kbd> 选择　<kbd>D</kbd> 绘制　<kbd>R</kbd> 时间区间　<kbd>A</kbd> 箭头　<kbd>I</kbd> 间隔　<kbd>T</kbd> 文字</p><p><kbd>Ctrl S</kbd> 下载工程　<kbd>Ctrl Z</kbd> 撤销　<kbd>Ctrl Y</kbd> 重做　<kbd>Delete</kbd> 删除选中对象<br><kbd>Ctrl C</kbd> 复制区间　<kbd>Ctrl V</kbd> 从所选区间起点粘贴　<kbd>Shift</kbd> 拖动时关闭吸附</p><p>选择信号后，画布上方的小方块是跳变点，可以左右拖动。在属性面板精确输入时间。双击数字波形上半部置高、下半部置低；双击总线修改完整段。右键信号可打开事件表。</p><p>左侧复选框支持多信号选择。分组标题可折叠；搜索、折叠只影响画布视图，导出包含全部信号。</p><p>箭头、曲线、间隔和 Setup/Hold 都从起点拖向终点。选中后拖动圆形端点，或在属性面板指定时间、关联信号。时间断裂仅为视觉符号，不改变时间比例。</p><p>工程库使用本机 IndexedDB，自动保存使用浏览器缓存。下载 JSON 才能迁移到另一台电脑或备份；VCD 不保存标注。支持导入上一版工程。</p><p>协议模板和数值曲线用于设计说明；本工具不执行 RTL、PCIe/MIPI 协议一致性测试或模拟信号完整性分析。</p>`,null)}$('help').onclick=help;$('shortcuts').onclick=help;
document.addEventListener('keydown',e=>{let input=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('saveProject').click();return}if(input||$('dialog').open)return;let key=e.key.toLowerCase();if(e.ctrlKey||e.metaKey){if(key==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}else if(key==='y'){e.preventDefault();$('redo').click()}else if(key==='c'&&range&&selection.size){e.preventDefault();let a=Math.min(range.a,range.b),b=Math.max(range.a,range.b);if(a===b)return;clipboard=WC.copyRange(doc,[...selection],a,b);toast('已复制时间区间')}else if(key==='v'&&clipboard&&selection.size){e.preventDefault();try{let next=WC.copy(doc);WC.pasteRange(next,[...selection],clipboard,range?Math.min(range.a,range.b):0);WC.validate(next);checkpoint();doc=next;commit();toast('已粘贴')}catch(err){toast(err.message)}}return}if(key==='delete'||key==='backspace'){e.preventDefault();if(chosen?.annotation){checkpoint();doc.annotations=doc.annotations.filter(a=>a.id!==chosen.annotation);chosen=null;commit()}else if(chosen?.signal&&chosen.time>0){checkpoint();let s=doc.signals.find(s=>s.id===chosen.signal);s.events=s.events.filter(n=>n.t!==chosen.time);chosen=null;commit()}else if(selection.size)deleteSignals(selection)}if(key==='escape'){if(drag)endDrag(true);chosen=null;range=null;setTool('select');render()}let map={v:'select',d:'draw',r:'range',a:'arrow',i:'interval',t:'text'};if(map[key])setTool(map[key]);if(key==='+'||key==='=')zoom(1.35);if(key==='-')zoom(1/1.35)});
setTool('select');render();requestAnimationFrame(()=>{zoom(1,true)});
